    /**
     * Stop FollowMe mode.
     *
     * @return The result of the request.
     */
    fun stop(): Result = Result.fromValue(native.stop())

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class FollowMeException(val result: Result, message: String) : Exception(message)
